// Generated from src/registry/sources/control-ui/recipes/swap.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const swapKnobs = ["--cui-swap-animation-duration", "--cui-swap-easing", "--cui-swap-label-inset", "--cui-swap-icon-scale"] as const;
export type SwapKnobStyle = Partial<Record<(typeof swapKnobs)[number], string>>;

@layer components {
  :where([data-control-family="swap"][data-slot="root"]) {
    --cui-swap-animation-duration: var(--duration-slow);
    --cui-swap-easing: var(--ease-emphasized);
    --cui-swap-label-inset: 60%;
    --cui-swap-icon-scale: 0.5;
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: inherit;
    inline-size: var(--_swap-inline-size, auto);
    transition: inline-size var(--cui-swap-animation-duration) var(--cui-swap-easing);
  }

  :where([data-control-family="swap"][data-slot="item"]) {
    display: inline-flex;
    flex: none;
    align-items: center;
    gap: inherit;
    white-space: nowrap;
  }

  :where([data-control-family="swap"][data-slot="item"]:not([data-state="active"])) {
    position: absolute;
    inset-block: 0;
    inset-inline-start: 0;
    opacity: 0;
    pointer-events: none;
  }

  :where([data-control-family="swap"][data-slot="item"][data-state="inactive"]) {
    visibility: hidden;
  }

  :where([data-control-family="swap"][data-slot="label"]) {
    display: inline-block;
  }

  :where([data-control-family="swap"][data-swapped] > [data-slot="item"][data-state="active"]) {
    animation: cui-swap-item-enter var(--cui-swap-animation-duration) var(--cui-swap-easing) both;
  }

  :where([data-control-family="swap"][data-swapped] > [data-slot="item"][data-state="exiting"]) {
    animation: cui-swap-item-exit var(--cui-swap-animation-duration) var(--cui-swap-easing) both;
  }

  :where(
    [data-control-family="swap"][data-swapped]
      > [data-slot="item"][data-state="active"]
      > :not(svg, [data-slot="icon"], [data-control-family="spinner"])
  ) {
    animation: cui-swap-label-enter var(--cui-swap-animation-duration) var(--cui-swap-easing) both;
  }

  :where(
    [data-control-family="swap"][data-swapped]
      > [data-slot="item"][data-state="exiting"]
      > :not(svg, [data-slot="icon"], [data-control-family="spinner"])
  ) {
    animation: cui-swap-label-exit var(--cui-swap-animation-duration) var(--cui-swap-easing) both;
  }

  :where(
    [data-control-family="swap"][data-swapped]
      > [data-slot="item"][data-state="active"]
      > :is(svg, [data-slot="icon"], [data-control-family="spinner"])
  ) {
    animation: cui-swap-icon-enter var(--cui-swap-animation-duration) var(--cui-swap-easing) both;
  }

  :where(
    [data-control-family="swap"][data-swapped]
      > [data-slot="item"][data-state="exiting"]
      > :is(svg, [data-slot="icon"], [data-control-family="spinner"])
  ) {
    animation: cui-swap-icon-exit var(--cui-swap-animation-duration) var(--cui-swap-easing) both;
  }

  @keyframes cui-swap-item-enter {
    from {
      opacity: 0;
      filter: blur(var(--blur-xs));
    }
  }

  @keyframes cui-swap-item-exit {
    from {
      opacity: 1;
      filter: blur(0);
    }
    to {
      opacity: 0;
      filter: blur(var(--blur-xs));
      visibility: hidden;
    }
  }

  @keyframes cui-swap-label-enter {
    from {
      translate: 0 var(--cui-swap-label-inset);
    }
  }

  @keyframes cui-swap-label-exit {
    to {
      translate: 0 calc(var(--cui-swap-label-inset) * -1);
    }
  }

  @keyframes cui-swap-icon-enter {
    from {
      scale: var(--cui-swap-icon-scale);
    }
  }

  @keyframes cui-swap-icon-exit {
    to {
      scale: var(--cui-swap-icon-scale);
    }
  }
}

@property --cui-swap-animation-duration {
  syntax: "<time>";
  inherits: true;
  initial-value: 0s;
}

@property --cui-swap-easing {
  syntax: "*";
  inherits: true;
}

@property --cui-swap-label-inset {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-swap-icon-scale {
  syntax: "<number>";
  inherits: true;
  initial-value: 1;
}

"use client";

import type { ComponentProps, CSSProperties, ReactNode } from "react";
import { Children, createContext, useContext, useLayoutEffect, useRef, useState } from "react";
import type { SwapKnobStyle } from "@/components/control-ui/knob-contracts/swap-knobs";

export type SwapItemState = "active" | "exiting" | "inactive";

type SwapTransition = { value: string; previous: string | null };

const SwapContext = createContext<SwapTransition | null>(null);

function useSwap() {
  const context = useContext(SwapContext);
  if (!context) throw new Error("SwapItem must be rendered inside <Swap>.");
  return context;
}

function fitRootToItem(item: HTMLSpanElement) {
  const root = item.parentElement;
  if (!root) return;
  const observer = new ResizeObserver(([entry]) => {
    const [borderBox] = entry.borderBoxSize;
    // A hidden item measures 0: release the width so the next reveal snaps to size instead of growing from 0.
    if (borderBox.inlineSize === 0) root.style.removeProperty("--_swap-inline-size");
    else root.style.setProperty("--_swap-inline-size", `${borderBox.inlineSize}px`);
  });
  observer.observe(item);
  return () => observer.disconnect();
}

export type SwapProps = Omit<ComponentProps<"span">, "style"> & {
  value: string;
  style?: CSSProperties & SwapKnobStyle;
};

export function Swap({ value, children, ...props }: SwapProps) {
  const [transition, setTransition] = useState<SwapTransition>({ value, previous: null });
  if (transition.value !== value) setTransition({ value, previous: transition.value });

  return (
    <SwapContext.Provider value={transition}>
      <span
        data-control-ui="swap"
        data-control-family="swap"
        data-slot="root"
        data-swapped={transition.previous === null ? undefined : ""}
        {...props}
      >
        {children}
      </span>
    </SwapContext.Provider>
  );
}

function itemState({ value, previous }: SwapTransition, itemValue: string): SwapItemState {
  if (itemValue === value) return "active";
  if (itemValue === previous) return "exiting";
  return "inactive";
}

function wrapLabelText(children: ReactNode): ReactNode {
  return Children.map(children, (child) =>
    typeof child === "string" || typeof child === "number" ? (
      <span data-control-ui="swap" data-control-family="swap" data-slot="label">
        {child}
      </span>
    ) : (
      child
    ),
  );
}

export type SwapItemProps = ComponentProps<"span"> & {
  value: string;
};

export function SwapItem({ value, children, ref, ...props }: SwapItemProps) {
  const state = itemState(useSwap(), value);
  const itemRef = useRef<HTMLSpanElement | null>(null);
  const fitsRoot = state === "active";
  useLayoutEffect(() => (fitsRoot && itemRef.current ? fitRootToItem(itemRef.current) : undefined), [fitsRoot]);

  return (
    <span
      data-control-ui="swap"
      data-control-family="swap"
      data-slot="item"
      data-state={state}
      aria-hidden={state === "active" ? undefined : true}
      {...props}
      ref={(item) => {
        itemRef.current = item;
        if (typeof ref === "function") return ref(item);
        if (ref) ref.current = item;
      }}
    >
      {wrapLabelText(children)}
    </span>
  );
}
